import{_ as a,o as t,c as r,l as o,t as s,N as n}from"./chunks/framework.Gjrf2Eoj.js";const f=JSON.parse('{"title":"bashbug | x-cmd man (bash man1) | report a bug in bash","titleTemplate":false,"description":"x-cmd man (bash man1 Manual Page) | bashbug - report a bug in bash","frontmatter":{"pageClass":"x-man","head":[["meta",{"name":"og:title","content":"bashbug | x-cmd man (bash man1) | report a bug in bash"}],["meta",{"name":"og:description","content":"x-cmd man (bash man1 Manual Page) | bashbug - report a bug in bash"}]]},"headers":[],"params":{"isMan":true,"man":"bashbug","category":"bash man1","desc":"report a bug in bash"},"relativePath":"bash/man1/bashbug.md","filePath":"bash/man1/bashbug.md"}'),i={name:"bash/man1/bashbug.md"},h={class:"visually-hidden"},d=n('<h2 id="name" tabindex="-1">NAME <a class="header-anchor" href="#name" aria-label="Permalink to &quot;NAME&quot;">​</a></h2><p>bashbug - report a bug in bash</p><h2 id="synopsis" tabindex="-1">SYNOPSIS <a class="header-anchor" href="#synopsis" aria-label="Permalink to &quot;SYNOPSIS&quot;">​</a></h2><p><strong>bashbug</strong> [<em>--version</em>] [<em>--help</em>] [<em>email-address</em>]</p><h2 id="description" tabindex="-1">DESCRIPTION <a class="header-anchor" href="#description" aria-label="Permalink to &quot;DESCRIPTION&quot;">​</a></h2><p><strong>bashbug</strong> is a shell script to help the user compose and mail bug reports concerning bash in a standard format. <strong>bashbug</strong> invokes the editor specified by the environment variable</p><p><strong>EDITOR</strong> on a temporary copy of the bug report format outline. The user must fill in the appropriate fields and exit the editor. <strong>bashbug</strong> then mails the completed report to <em><a href="mailto:bug-bash@gnu.org" target="_blank" rel="noreferrer">bug-bash@gnu.org</a></em>, or <em>email-address</em>. If the report cannot be mailed, it is saved in the file <em>dead.bashbug</em> in the invoking user&#39;s home directory.</p><p>The bug report format outline consists of several sections. The first section provides information about the machine, operating system, the bash version, and the compilation environment. The second section should be filled in with a description of the bug. The third section should be a description of how to reproduce the bug. The optional fourth section is for a proposed fix. Fixes are encouraged.</p><h2 id="environment" tabindex="-1">ENVIRONMENT <a class="header-anchor" href="#environment" aria-label="Permalink to &quot;ENVIRONMENT&quot;">​</a></h2><p><strong>bashbug</strong> will utilize the following environment variables if they exist:</p><dl><dt><strong>EDITOR</strong></dt><dd>Specifies the preferred editor. If</dd></dl><p><strong>EDITOR</strong> is not set, <strong>bashbug</strong> attempts to locate a number of alternative editors, including <strong>emacs</strong>. If <strong>bashbug</strong> cannot locate any of the alternative editors, it attempts to execute <strong>vi</strong>.</p><dl><dt><strong>HOME</strong></dt><dd>Directory in which the failed bug report is saved if the mail fails.</dd><dt><strong>TMPDIR</strong></dt><dd>Directory in which to create temporary files and directories.</dd></dl><h2 id="see-also" tabindex="-1">SEE ALSO <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;SEE ALSO&quot;">​</a></h2><dl><dt><em>bash</em>(1)</dt><dd># AUTHORS</dd></dl><p>Brian Fox, Free Software Foundation <br> <a href="mailto:bfox@gnu.org" target="_blank" rel="noreferrer">bfox@gnu.org</a></p><p>Chet Ramey, Case Western Reserve University <br> <a href="mailto:chet@po.cwru.edu" target="_blank" rel="noreferrer">chet@po.cwru.edu</a></p>',17);function l(e,b,m,g,c,p){return t(),r("div",null,[o("h1",h,s(e.$params.man),1),d])}const _=a(i,[["render",l]]);export{f as __pageData,_ as default};
